  ('d0ed2b30-545e-4293-bd57-d9eb36612f61', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जानवरों मेें गधा सबसे ज्यादा बुद्धिहीन समझा जाता है। हम जब किसी आदमी को परले दरजे का बेवकूफ कहना चाहते हैं, तो उसे गधा कहते हैं। गधा सचमुच बेवकूफ है, या उसके सीधेपन, उसकी निरापद सहिष््णुता ने उसे यह पदवी दे दी है, इसका निश्चय नहीं किया जा सकता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
