  ('921a5a53-e4c1-4927-8cae-85d5d486b91b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जितना चाहो गरीब को मारो, चाहे जैसी खराब, सड़ी हुई घास सामने डाल दो, उसके चेहरे पर कभी असंतोष की छाया भी न दिखाई देगी। वैशशाख मेें चाहे एकाध बार कुलेल कर लेता हो; पर हमने तो उसे कभी खुशश होते नहीं देखा। उसके चेहरे पर एक स््‍थथाथायी विषाद स््‍थथाथायी रूप से छाया रहता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('23cfb562-5553-470a-8ea6-aa7b1901b6c9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुख-दुख, हानि-लाभ, किसी भी दशशा मेें उसे बदलते नहीं देखा। ॠषियों-मुनियों के जितने गुणण हैं, वे सभी उसमेें पराकाष्ठा को पहुँच गए हैं; पर आदमी उसे बेवकूफ कहता है। सद्गुणोों का इतना अनादर कहीं नहीं देखा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('516be261-5cf2-4457-8d37-b63dac300f36', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कदाचित सीधापन संसार के लिए उपयुक्‍त नहीं है। देखिए न, भारतवासियों की अफ्ीका मेें क््ययाया दुर््दशशा हो रही है? क््यों अमरीका मेें उन््हें घुसने नहीं दिया जाता?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1743502f-145b-4e6b-8e70-f5aff1cca341', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बेचारे शशराब नहीं पीते, चार पैसे कुसमय के लिए बचाकर रखते हैं, जी तोड़कर काम करते हैं, किसी से लड़ाई-झगड़ा नहीं करते, चार बातें सुनकर गम खा जाते हैं फिर भी बदनाम हैं। कहा जाता है, वे जीवन के आदर््श को नीचा करते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aace79a7-614a-465f-823f-10f2e9c4d472', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर वे भी इ«टट का जवाब पत््थर से देना सीख जाते, तो शशायद सभ्य कहलाने लगते। जापान की मिसाल सामने है। एक ही विजय ने उसे संसार की सभ्य जातियों मेें गण्य बना दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0fa0e01d-ee09-4719-a15b-fc712d2d2d1f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन गधे का एक छोटटा भाई और भी है, जो उससे कम ही गधा है, और वह है ‘बैल’। जिस अर््थ मेें हम ‘गधा’ शशब्द का प्रयोग करते हैं, कुछ उसी से मिलते-जुलते अर््थ मेें ‘बछिया के ताऊ’ का भी प्रयोग करते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3168f019-ab33-444f-8c35-edba2bd593a1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ लोग बैल को शायद बेवकूफों मेें सर््वश्ेष्ठ कहेंगे; मगर हमारा विचार ऐसा नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5132947e-f5e6-401c-bd1b-4cd35cc169ae', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बैल कभी-कभी मारता भी है, कभी-कभी अड़ियल बैल भी देखने में आता है। और भी कई रीतियों से अपना असंतोष प्रकट कर देता है; अतएव उसका स्थान गधे से नीचा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('71aa3971-57c4-4f99-b0bc-f29fcf057510', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी के दोनों बैलों के नाम थे हीरा और मोती। दोनों पछाईं जाति के थे— देखने में सुंदर, काम में चौकस, डील में ऊँचे। बहुत दिनों साथ रहते-रहते दोनों में भाईचारा हो गया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1b66354f-4d56-4874-8dee-7365462fbcc3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों आमने-सामने या आस-पास बैठे हुए एक-दूसरे से मूक-भाषा में विचार-विनिमय करते थे। एक, दूसरे के मन की बात कैसे समझ जाता था, हम नहीं कह सकते। अवश्य ही उनमें कोई ऐसी गुप्त शक्ति थी जिससे जीवों में श्रेष्ठता का दावा करने वाला मनुष्य वंचित है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('907e388f-f207-4969-8978-5945baadfa85', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों एक-दूसरे को चाटकर और सूँघकर अपना प्रेम प्रकट करते, कभी-कभी दोनों सींग भी मिला लिया करते थे— विग्रह के नाते से नहीं, केवल विनोद के भाव से, आत्मीयता के भाव से, जैसे दोस्तों में घनिष्ठता होते ही धौल-धप्पा होने लगता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cc73dda5-fe84-4d75-8c31-41ebe81f0fd6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जिस वक्त ये दोनों बैल हल या गाड़ी में जोत दिए जाते और गरदन हिला-हिलाकर चलते, उस वक्त हरएक की यही चेष्टा होती थी कि ज्यादा-से-ज्यादा बोझ मेरी ही गरदन पर रहे। दिन-भर के बाद दोपहर या संध्या को दोनों खुलते, तो एक-दूसरे को चाट-चूटकर अपनी थकान मिटा लिया करते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a9407103-d76b-4c54-97ea-6e7075f3d9ea', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नाँद में खली-भूसा पड़ जाने के बाद दोनों साथ उठते, साथ नाँद में मुँह डालते और साथ ही बैठते थे। एक मुँह हटा लेता, तो दूसरा भी हटा लेता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('618ebfac-48b0-4a34-a2d7-5d7acf565185', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संयोग की बात, झूरी ने एक बार गोई को ससुराल भेज दिया। बैलों को क्या मालूम, वे क्यों भेजे जा रहे हैं। समझे, मालिक ने हमें बेच दिया। अपना यों बेचा जाना उन्हें अच्छा लगा या बुरा, कौन जाने, पर झूरी के साले गया को घर तक गोई ले जाने में दाँतों पसीना आ गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d92e7a2a-3f73-4ed6-b573-00525e41b2d4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पीछे से हाँकता तो दोनों दाएँ-बाएँ भागते; पगहिया पकड़कर आगे से खींचता, तो दोनों पीछे को जोर लगाते। मारता तो दोनों सींग नीचे करके हुँकारते। अगर ईश्वर ने उन्हें वाणी दी होती, तो झूरी से पूछते− तुम हम गरीबों को क्यों निकाल रहे हो?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d8b3e225-6586-43d1-ac24-9a9d01dcc7db', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संध्या समय दोनों बैल अपने नए स्थान पर पहुँचे। दिन-भर के भूखे थे, लेकिन जब नाँद में लगाए गए, तो एक ने भी उसमें मुँह न डाला। दिल भारी हो रहा था। जिसे उन्होंने अपना घर समझ रखा था, वह आज उनसे छूट गया था। यह नया घर, नया गाँव, नए आदमी, सब उन्हें बेगानों-से लगते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9ecc79de-c1de-4f81-b407-5e9a395afe10', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनोों ने अपनी मूक-भाषा में सलाह की, एक-दूसरे को कनखियोों से देखा और लेट गए। जब गाँव में सोता पड़ गया, तो दोनोों ने जोर मारकर पगहे तुड़ा डाले और घर की तरफ चले। पगहे बहुत मजबूत थे। अनुमान न हो सकता था कि कोई बैल उन््हें तोड़ सकेगा; पर इन दोनोों में इस समय दूनी शक्‍तति आ गई थी। एक-एक झटके में रस्ससियाँ टूट गइ«।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5a8eed3b-917c-4a9b-8860-ddc15753b3f2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी प्ातःकाल सोकर उठा, तो देखा कि दोनोों बैल चरनी पर खड़े हैं। दोनोों की गरदनोों में आधा-आधा गराँव लटक रहा है। घुटने तक पाँव कीचड़ से भरे हैं और दोनोों की आँखों में विद्ोहमय स््ननेह झलक रहा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('07770c51-1198-4aca-bf83-514fcae13c6f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी बैलों को देखकर स््ननेह से गद्गद हो गया। दौड़कर उन््हें गले लगा लिया। प्ेमालिंगन और चुंबन का वह दृश््य बड़ा ही मनोहर था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('337c0779-1425-40b1-ab7b-60ed13fbc9e8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर और गाँव के लड़के जमा हो गए और तालियाँ बजा-बजाकर उनका स््ववावागत करने लगे। गाँव के इतिहास में यह घटना अभूतपूर्व न होने पर भी महत्वपूर््ण थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dc6162e0-abcb-4c06-b3a0-56ce8b867b2c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाल-सभा ने निश्‍चय किया, दोनोों पशु-वीरों को अभिनंदन-पत्र देना चाहिए। कोई अपने घर से रोटियाँ लाया, कोई गुड़, कोई चोकर, कोई भूसी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ac0b89b-104e-4cc3-9be6-756487a3f885', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बालक ने कहा− “ऐसे बैल किसी के पास न होंगे।” दूसरे ने समर््थन किया− “इतनी दूर से दोनोों अकेले चले आए।” तीसरा बोला− “बैल नहीीं हैं वे, उस जनम के आदमी हैं।” इसका प्रतिवाद करने का किसी को साहस न हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
