  ('04903135-a051-4208-97e6-14caba42eb92', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी प्ातःकाल सोकर उठा, तो देखा कि दोनोों बैल चरनी पर खड़े हैं। दोनोों की गरदनोों में आधा-आधा गराँव लटक रहा है। घुटने तक पाँव कीचड़ से भरे हैं और दोनोों की आँखों में विद्ोहमय स््ननेह झलक रहा है। झूरी बैलों को देखकर स््ननेह से गद्गद हो गया। दौड़कर उन््हें गले लगा लिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6b3c102e-8522-4f79-ae1c-ef45f4e07441', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर और गाँव के लड़के जमा हो गए और तालियाँ बजा-बजाकर उनका स््ववावागत करने लगे। गाँव के इतिहास में यह घटना अभूतपूर्व न होने पर भी महत्वपूर््ण थी। बाल-सभा ने निश्‍चय किया, दोनोों पशु-वीरों को अभिनंदन-पत्र देना चाहिए। कोई अपने घर से रोटियाँ लाया, कोई गुड़, कोई चोकर, कोई भूसी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5f1a160b-f73b-426c-9a1c-1fa78b8bde27', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी की स्‍‍त््री्री ने बैलों को द्ार पर देखा, तो जल उठी। बोली− “कैसे नमक-हराम बैल हैं कि एक दिन वहाँ काम न किया; भाग खड़े हुए।”
