  ('17213c36-8aad-45ce-91c3-d3efd71ee57c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज दोनों के सामने फिर वही सूखा भूसा लाया गया। दोनों चुपचाप खड़े रहे। घर के लोग भोजन करने लगे। उस वक्‍त एक छोटटी-सी लड़की दो रोटियाँ लिए निकली और दोनों के मुँह मेें देकर चली गई। उस एक रोटटी से इनकी भूख तो क््ययाया शशांत होती; पर दोनों के हृदय को मानो भोजन मिल गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c1c83b46-9015-40b0-a915-cb212a394439', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रेम के इस प्रसाद की यह बरकत थी कि दो-दो गाल सूखा भूसा खाकर भी दोनों दुर््बल न होते थे, मगर दोनों की आँखों मेें, रोम-रोम मेें विद्ोह भरा हुआ था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9aca458f-847c-4550-b6e7-f0faece10f18', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन मोती ने मूक-भाषा मेें कहा− “अब तो नहीं सहा जाता, हीरा!” “क््ययाया करना चाहते हो?” “एकाध को सींगों पर उठाकर फेेंक दूँगा।” “लेकिन जानते हो, वह प्यारी लड़की, जो हमेें रोटियाँ खिलाती है, उसी की लड़की है, जो इस घर का मालिक है। यह बेचारी अनाथ न हो जाएगी?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('59ada55a-1de2-46b9-878c-65d4f2f47696', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तो मालकिन को न फेेंक दूँ। वही तो उस लड़की को मारती है।” “लेकिन औरत जात पर सींग चलाना मना है, यह भूले जाते हो।” “तुम तो किसी तरह से निकलने ही नहीं देते। बताओ, तुड़ाकर भाग चलें।” “हाँ, यह मैं स््ववीवीकार करता, लेकिन इतनी मोटटी रस््ससीसी टटूटटेगी कैसे?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5be21c26-64c1-4892-a442-81d66eeaf643', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“इसका एक उपाय है। पहले रस््ससीसी को थोड़ा-सा चबा लो। फिर एक झटटके मेें टटूटट जाती है।” रात को जब बालिका रोटियाँ खिलाकर चली गई, तो दोनों रस््ससियाँ चबाने लगे, पर मोटटी रस््ससीसी मुँह मेें न आती थी। बेचारे बार-बार जोर लगाकर रह जाते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5ccca2d7-10cd-400b-a02c-47951d352c62', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा घर का द्ार खुला और वही लड़की निकली। दोनों सिर झुकाकर उसका हाथ चाटटने लगे। दोनों की पूँछें खड़ी हो गइ«। उसने उनके माथे सहलाए और बोली– “खोले देती हूँ। चुपके से भाग जाओ, नहीं तो यहाँ लोग तुम््हें मार डालेंगे। आज घर मेें सलाह हो रही है कि इनकी नाकों मेें नाथ डाल दी जाएँ।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5457d827-b069-4dd5-b633-57560ed23e8b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसने गराँव खोल दिया, पर दोनों चुपचाप खड़े रहे। मोती ने अपनी भाषा मेें पूछा− “अब चलते क््यों नहीं?” हीरा ने कहा− “चलें तो, लेकिन कल इस अनाथ पर आफत आएगी। सब इसी पर संदेह करेंगे।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ce69ed1b-36eb-453e-8d11-3fe540428bb4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा बालिका चिल्लाई− “दोनों फूफावाले बैल भागे जा रहे हैं। ओ दादा! दादा! दोनों बैल भागे जा रहे हैं, जल्दी दौड़ो।” गया हड़बड़ाकर भीतर से निकला और बैलों को पकड़ने चला। वे दोनों भागे। गया ने पीछा किया। वह और भी तेज हुए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4a1f3b2f-3da6-4383-80d8-98a5e3c494fc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गया ने शशोर मचाया। फिर गाँव के कुछ आदमियोों को भी साथ लेने के लिए लौटटा। दोनों मित्रों को भागने का मौका मिल गया। सीधे दौड़ते चले गए। यहाँ तक कि मार््ग का ज्ान न रहा। जिस परिचित मार््ग से आए थे, उसका यहाँ पता न था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ac388911-9121-4627-8dba-2f9ec1da3f43', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नए-नए गाँव मिलने लगे। तब दोनों एक खेत के किनारे खड़े होकर सोचने लगे, अब क््ययाया करना चाहिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('39434d64-d3b9-401d-ba8c-9be04733b965', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों भूख से व्याकुल हो रहे थे। खेत में मटर खड़ी थी। चरने लगे। रह-रहकर आहट ले लेते थे, कोई आता तो नहीं है। जब पेट भर गया और दोनों ने आजादी का अनुभव किया तो मस्त होकर उछलने-कूदने लगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('afc96e30-0c7d-4c87-8041-5381ed5347f3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अरे! यह क्या? कोई साँड़ डौंकता चला आ रहा है। हाँ, साँड़ ही है। वह सामने आ पहुँचा। दोनों मित्र बगलें झाँक रहे हैं। साँड़ पूरा हाथी है। उससे भिड़ना जान से हाथ धोना है; लेकिन न भिड़ने पर भी तो जान बचती नहीं नजर आती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d480a7e6-fc1e-4827-bd1f-77bbd796f539', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने मूक-भाषा में कहा− “बुरे फँसे। जान बचेगी? कोई उपाय सोचो।” हीरा ने चिंतित स्वर में कहा− “अपने घमंड में भूला हुआ है। आरजू-विनती न सुनेगा।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('55729042-2794-4b61-b547-c45764fff000', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“भाग क्यों न चलें?” “भागना कायरता है।” “तो फिर यहीं मरो। बंदा तो नौ-दो-ग्यारह होता है।” “और जो दौड़ाए?” “तो फिर कोई उपाय सोचो जल्द!”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0ec12137-1767-40e9-bd8e-75057342565a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“उपाय यही है कि उस पर दोनों जने एक साथ चोट करें। मैं आगे से रगेदता हूँ, तुम पीछे से रगेदो, दोहरी मार पड़ेगी, तो भाग खड़ा होगा। मेरी ओर झपटे, तुम बगल से उसके पेट में सींग घुसेड़ देना। जान जोखिम है; पर दूसरा उपाय नहीं है।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3c76478f-cbe4-4933-b3dc-f03751dc2e05', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों मित्र जान हथेलियों पर लेकर लपके। साँड़ को भी संगठित शत्रुओं से लड़ने का तजुरबा न था। वह तो एक शत्रु से मल्लयुद्ध करने का आदी था। ज्योंही हीरा पर झपटा, मोती ने पीछे से दौड़ाया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e7485c25-d2e4-4274-a905-b13512ab842e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने देखा− खेल में झगड़ा हुआ चाहता है तो किनारे हट गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8309492d-4a18-4028-8bc2-60edd6dfe6b4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तुम भी बेतहाशा भागे। वहीं उसे मार गिराना था।” “उसे मार गिराते, तो दुनिया क्या कहती? वह अपना धर्म छोड़ दे, लेकिन हम अपना धर्म क्यों छोड़ें?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6ce5a182-d32d-4b8b-a4f7-b37e5b46e91f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने हीरा को कई कदम पीछे हटा दिया, यहाँ तक कि वह एक खाई में गिर गया। तब उसे भी क्रोध आया। संभलकर उठा और फिर मोती से भिड़ गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2f64f935-9715-4a21-a547-28e29b78f0ad', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाड़े की दीवार कच्ची थी। हीरा मजबूत तो था ही, अपने नुकीले सींग दीवार मेें गड़ा दिए और जोर मारा, तो मिटट्टटी का एक चिप्पड़ निकल आया। फिर तो उसका साहस बढ़ा। उसने दौड़-दौड़कर दीवार पर चोटेें कीं और हर चोटट मेें थोड़ी-थोड़ी मिटट्टटी गिराने लगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0e066dbe-5e5a-40cb-8f1f-28478a06cc69', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसी समय काँजीहौस का चौकीदार लालटटेन लेकर जानवरों की हाजिरी लेने आ निकला। हीरा का यह उजड्डपन देखकर उसने उसे कई डंडे रसीद किए और मोटटी-सी रस््ससीसी से बाँध दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('257548e9-91f4-4d53-948a-f5bf2d2227e1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने पड़े-पड़े कहा− “आखिर मार खाई, क््ययाया मिला?” “अपने बूते-भर जोर तो मार दिया।” “ऐसा जोर मारना किस काम का कि और बंधन मेें पड़ गए।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('52182152-b8b1-49fc-9dd1-94e33edc3006', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“जान से हाथ धोना पड़ेगा।” “कुछ परवाह नहीं। यों भी तो मरना ही है। सोचो, दीवार खुद जाती तो कितनी जानें बच जातीं। इतने भाई यहाँ बंद हैं। किसी की देह मेें जान नहीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ed9941e8-e51c-4111-a489-e46af5c8dc18', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“हाँ, यह बात तो है। अच्छा, तो ला, फिर मैं भी जोर लगाता हूँ।” मोती ने भी दीवार मेें उसी जगह सींग मारा। थोड़ी-सी मिटट्टटी गिरी और फिर हिम््मत बढ़ी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d2f5ccc8-37b4-4027-a16a-bd6ad1363d50', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर तो वह दीवार मेें सींग लगाकर इस तरह जोर करने लगा, मानो किसी प्रतिद्ंद्ी से लड़ रहा है। आखिर कोई दो घंटटे की जोर-आजमाई के बाद दीवार ऊपर से लगभग एक हाथ गिर गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2040abbe-39fb-4488-acad-2ca1625143de', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने सिर लटटकाए हुए जवाब दिया− “मुझे तो मालूम होता है, प्राणण निकल रहे हैं।” “इतनी जल्द हिम््मत न हारो भाई! यहाँ से भागने का कोई उपाय निकालना चाहिए।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('87073a79-8da6-4c92-af45-ce8c6d9b1b42', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“बस इसी बूते पर अकड़ते थे!” “सारी अकड़ निकल गई।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('db0634df-8a5b-4b86-8b9c-3cabd31c92dc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“जोर तो मारता ही जाऊँगा, चाहे कितने ही बंधन पड़ते जाएँ।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f00b6d7d-04e1-4a51-b0a1-3e1e0b391dc6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती गर््व से बोला− “जिस अपराध के लिए तुम्हारे गले मेें बंधन पड़ा, उसके लिए अगर मुझ पर मार पड़े, तो क््ययाया चिंता। इतना तो हो ही गया कि नौ-दस प्राणियोों की जान बच गई। वे सब तो आशशीर््ववाद देंगे।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
