  ('c984f818-e0a5-46e4-9bbb-21b73bd23996', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने पूछा− “तुम दोनों क््यों नहीं भाग जाते?” एक गधे ने कहा− “जो कहीं फिर पकड़ लिए जाएँ!” “तो क््ययाया हरज है। अभी तो भागने का अवसर है।” “हमेें तो डर लगता है, हम यहीं पड़े रहेंगे।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('556afe98-8a68-415c-8199-ee992baaffe8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भोर होते ही मुंशशी और चौकीदार तथा अन्य कर््मचारियों मेें कैसी खलबली मची, इसके लिखने की जरूरत नहीं। बस, इतना ही काफी है कि मोती की खूब मरम््मत हुई और उसे भी मोटटी रस््ससीसी से बाँध दिया गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c938e219-451f-49b0-9416-259675cd86dc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन बाड़े के सामने डुग्गी बजने लगी और दोपहर होते-होते वहाँ पचास-साठ आदमी जमा हो गए। तब दोनों मित्र निकाले गए और उनकी देखभाल होने लगी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('109a9619-376c-4579-bb22-955940479629', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दीवार का गिरना था कि अधमरे-से पड़े हुए सभी जानवर चेत उठे। तीनों घोड़़ियाँ सरपटट भाग निकलीं। फिर बकरियाँ निकलीं। इसके बाद भैंसें भी खिसक गइ; पर गधे अभी तक ज््यों-के-त््यों खड़े थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aee6fe63-4a96-4ce8-aa94-b02d48afdd7e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने आँखों मेें आँसू लाकर कहा− “तुम मुझे इतना स््ववार्थी समझते हो, हीरा? हम और तुम इतने दिनों एक साथ रहे हैं। आज तुम विपत्ति मेें पड़ गए, तो मैं तुम््हें छोड़कर अलग हो जाऊँ।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('78069736-de51-4633-9769-ae286dd2618c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह कहते हुए मोती ने दोनों गधों को सींगों से मार-मारकर बाड़े के बाहर निकाला और तब अपने बंधु के पास आकर सो रहा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a765fe2b-15e9-4e66-b682-ae2816b9c526', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसने दूनी शक््‍तति से दूसरा धक््ककाका मारा, तो आधी दीवार गिर पड़ी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('96e9d421-add9-4b89-9e56-2428d22ffaed', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा एक दढ़ियल आदमी, जिसकी आँखें लाल थीं और मुद्रा अत्यंत कठोर, आया और दोनों मित्रों के कूल्हों में उँगली गोदकर मुंशी जी से बातें करने लगा। उसका चेहरा देखकर अंतर्ज्ञान से दोनों मित्रों के दिल काँप उठे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('7fdbfea7-e634-46b9-a195-27454be12bca', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने कहा− “गया के घर से नाहक भागे। अब जान न बचेगी।” मोती ने अश्रद्धा के भाव से उत्तर दिया− “कहते हैं, भगवान सबके ऊपर दया करते हैं। उन्हें हमारे ऊपर क्यों दया नहीं आती।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ce33e82f-6c13-49df-8e94-2cb296ec4af9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नीलाम हो जाने के बाद दोनों मित्र उस दढ़ियल के साथ चले। दोनों की बोटटी-बोटटी काँप रही थी। बेचारे पाँव तक न उठा सकते थे, पर भय के मारे गिरते-पड़ते भागे जाते थे; क्योंकि वह ज़रा भी चाल धीमी हो जाने पर जोर से डंडा जमा देता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('886ec1c7-48b0-462b-be81-ea19c6dbacbd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राह में गाय-बैलों का एक रेवड़ हरे-हरे हार में चरता नजर आया। सभी जानवर प्रसन्न थे, चिकने, चपल। कोई उछलता था, कोई आनंद से बैठा पागुर करता था। कितना सुखी जीवन था इनका; पर कितने स्वार्थी हैं सब।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('1f6f4b8c-76cb-45b3-878e-d5832d95ddfd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा दोनों को ऐसा मालूम हुआ कि यह परिचित राह है। हाँ, इसी रास्ते से गया उन्हें ले गया था। वही खेत, वही बाग, वही गाँव मिलने लगे। प्रतिक्षण उनकी चाल तेज होने लगी। सारी थकान, सारी दुर्बलता गायब हो गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('0dacfded-377f-4e4f-8aba-01b60c8d18ab', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने कहा– “हमारा घर नगीच आ गया।” हीरा बोला– “भगवान की दया है।” “मैं तो अब घर भागता हूँ।” “यह जाने देगा?” “इसे मैं मार गिराता हूँ।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('12fa59a5-a693-4bd8-9ef3-019a79190beb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“भगवान के लिए हमारा मरना-जीना दोनों बराबर है। चलो, अच्छा ही है, कुछ दिन उसके पास तो रहेंगे। एक बार भगवान ने उस लड़की के रूप में हमें बचाया था। क्या अब न बचाएँगे?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d2a3381e-5db6-46e3-a1ab-bd6baa28ceec', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“यह आदमी छुरी चलाएगा। देख लेना।” “तो क्या चिंता है? माँस, खाल, सींग, हड्डी सब किसी-न-किसी काम आ जाएँगी।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('749498ee-f611-4a9f-93c7-d22a4c4706aa', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आ-आकर उनकी सूरत देखते और मन फीका करके चले जाते। ऐसे मृतक बैलों का कौन खरीदार होता?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b7cc0edb-7832-4740-b2a0-6406127e976c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दढ़ियल ने जाकर बैलों की रस्सियाँ पकड़ लीं। झूरी ने कहा– मेरे बैल हैं। 'तुम्हारे बैल कैसे? मैं मवेशीखाने से नीलाम लिए आता हूँ।' 'मैं तो समझता हूँ चुराए लिए आते हो! चुपके से चले जाओ। मेरे बैल हैं। मैं बेचूँगा तो बिकेंगे। किसी को मेरे बैल नीलाम करने का क्या अख़्तियार है?'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('db3318e8-4d1c-4f0b-8fe0-0002809caa59', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसी वक़्त मोती ने सींग चलाया। दढ़ियल पीछे हटा। मोती ने पीछा किया। दढ़ियल भागा। मोती पीछे दौड़ा। गाँव के बाहर निकल जाने पर वह रुका; पर खड़ा दढ़ियल का रास्ता देख रहा था। दढ़ियल दूर खड़ा धमकियाँ दे रहा था, गालियाँ निकाल रहा था, पत्थर फेंक रहा था। और मोती विजयी शूर की भाँति उसका रास्ता रोके खड़ा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9b20eeef-4b6c-43e8-9801-3c47df601adf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने कहा—'मैं डर रहा था कि कहीं तुम गुस्से में आकर मार न बैठो।' 'अगर वह मुझे पकड़ता, तो मैं बे-मारे न छोड़ता।' 'अब न आएगा।' 'आएगा तो दूर ही से खबर लूँगा। देखूँ, कैसे ले जाता है।' 'जो गोली मरवा दे?' 'मर जाऊँगा; पर उसके काम तो न आऊँगा।' 'हमारी जान को कोई जान ही नहीं समझता।' 'इसीलिए कि हम इतने सीधे हैं।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('47a7abe1-db01-4a77-892b-8b00f3fd0dce', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ज़रा देर में नाँदों में खली, भूसा, चोकर और दाना भर दिया गया और दोनों मित्र खाने लगे। झूरी खड़ा दोनों को सहला रहा था और बीसों लड़के तमाशा देख रहे थे। सारे गाँव में उछाह-सा मालूम होता था। उसी समय मालकिन ने आकर दोनों के माथे चूम लिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('146f7211-b5c9-4d08-9814-9c47450cf572', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी द्वार पर बैठा धूप खा रहा था। बैलों को देखते ही दौड़ा और उन्हें बारी-बारी से गले लगाने लगा। मित्रों की आँखों से आनंद के आँसू बहने लगे। एक झूरी का हाथ चाट रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3c40ea6d-fe87-47b7-8411-fb1836b82b98', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दढ़ियल झल्लाकर बैलों को ज़बरदस्ती पकड़ ले जाने के लिए बढ़ा। उसी वक़्त मोती ने सींग चलाया। दढ़ियल पीछे हटा। मोती ने पीछा किया। दढ़ियल भागा। मोती पीछे दौड़ा। गाँव के बाहर निकल जाने पर वह रुका; पर खड़ा दढ़ियल का रास्ता देख रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('11ae9893-8f5e-484f-88ce-1e1841490695', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी ने कहा– मेरे बैल हैं। 'तुम्हारे बैल कैसे? मैं मवेशीखाने से नीलाम लिए आता हूँ।' 'मैं तो समझता हूँ चुराए लिए आते हो! चुपके से चले जाओ। मेरे बैल हैं। मैं बेचूँगा तो बिकेंगे। किसी को मेरे बैल नीलाम करने का क्या अख़्तियार है?' 'जाकर थाने में रपट कर दूँगा।' 'मेरे बैल हैं। इसका सबूत यह है कि मेरे द्वार पर खड़े हैं।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('39e661c8-cd13-4d36-9068-b4c7f50c3bf1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने कहा—'मैं डर रहा था कि कहीं तुम गुस्से में आकर मार न बैठो।' 'अगर वह मुझे पकड़ता, तो मैं बे-मारे न छोड़ता।' 'अब न आएगा।' 'आएगा तो दूर ही से खबर लूँगा। देखूँ, कैसे ले जाता है।' 'जो गोली मरवा दे?' 'मर जाऊँगा; पर उसके काम तो न आऊँगा।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3b36a8ab-f592-4a0a-a4cf-cc0614f659b9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सारे गाँव में उछाह-सा मालूम होता था। उसी समय मालकिन ने आकर दोनों के माथे चूम लिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c1dc7110-ebc9-4700-abfc-b60af9e8b696', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जानवरों मेें गधा सबसे ज्यादा बुद्धिहीन समझा जाता है। हम जब किसी आदमी को परले दरजे का बेवकूफ कहना चाहते हैं, तो उसे गधा कहते हैं। गधा सचमुच बेवकूफ है, या उसके सीधेपन, उसकी निरापद सहिष््णुता ने उसे यह पदवी दे दी है, इसका निश्चय नहीं किया जा सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9c81ac37-519a-4be8-aecf-bcfba61be94e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गायें सींग मारती हैं, ब्याई हुई गाय तो अनायास ही सिंहनी का रूप धारणण कर लेती है। कुत्ता भी बहुत गरीब जानवर है, लेकिन कभी-कभी उसे भी क्रोध आ ही जाता है; किंतु गधे को कभी क्रोध करते नहीं सुना, न देखा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9a52fe2d-d456-415c-899b-3114a97a27cc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जितना चाहो गरीब को मारो, चाहे जैसी खराब, सड़ी हुई घास सामने डाल दो, उसके चेहरे पर कभी असंतोष की छाया भी न दिखाई देगी। वैशशाख मेें चाहे एकाध बार कुलेल कर लेता हो; पर हमने तो उसे कभी खुशश होते नहीं देखा। उसके चेहरे पर एक स््‍थथाथायी विषाद स््‍थथाथायी रूप से छाया रहता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a19154be-8740-4e05-90b3-05790d340dfc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुख-दुख, हानि-लाभ, किसी भी दशशा मेें उसे बदलते नहीं देखा। ॠषियों-मुनियों के जितने गुणण हैं, वे सभी उसमेें पराकाष्ठा को पहुँच गए हैं; पर आदमी उसे बेवकूफ कहता है। सद्गुणोों का इतना अनादर कहीं नहीं देखा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2f2a727a-e186-4e6d-8bd7-0c90ffeb8dce', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कदाचित सीधापन संसार के लिए उपयुक्‍त नहीं है। देखिए न, भारतवासियों की अफ्ीका मेें क््ययाया दुर््दशशा हो रही है? क््यों अमरीका मेें उन््हें घुसने नहीं दिया जाता? बेचारे शशराब नहीं पीते, चार पैसे कुसमय के लिए बचाकर रखते हैं, जी तोड़कर काम करते हैं, किसी से लड़ाई-झगड़ा नहीं करते, चार बातें सुनकर गम खा जाते हैं फिर भी बदनाम हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5479328d-5775-4ba2-be2f-416c15428731', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कहा जाता है, वे जीवन के आदर््श को नीचा करते हैं। अगर वे भी इ«टट का जवाब पत््थर से देना सीख जाते, तो शशायद सभ्य कहलाने लगते। जापान की मिसाल सामने है। एक ही विजय ने उसे संसार की सभ्य जातियों मेें गण्य बना दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d0f61124-eaa6-4ead-af0f-97b4809fa51a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जानवरों मेें गधा सबसे ज्यादा बुद्धिहीन समझा जाता है। हम जब किसी आदमी को परले दरजे का बेवकूफ कहना चाहते हैं, तो उसे गधा कहते हैं। गधा सचमुच बेवकूफ है, या उसके सीधेपन, उसकी निरापद सहिष््णुता ने उसे यह पदवी दे दी है, इसका निश्चय नहीं किया जा सकता। गायें सींग मारती हैं, ब्याई हुई गाय तो अनायास ही सिंहनी का रूप धारणण कर लेती है। कुत्ता भी बहुत गरीब जानवर है, लेकिन कभी-कभी उसे भी क्रोध आ ही जाता है; किंतु गधे को कभी क्रोध करते नहीं सुना, न देखा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('05479898-3979-427c-9d0a-4b589985b58c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जितना चाहो गरीब को मारो, चाहे जैसी खराब, सड़ी हुई घास सामने डाल दो, उसके चेहरे पर कभी असंतोष की छाया भी न दिखाई देगी। वैशशाख मेें चाहे एकाध बार कुलेल कर लेता हो; पर हमने तो उसे कभी खुशश होते नहीं देखा। उसके चेहरे पर एक स््‍थथाथायी विषाद स््‍थथाथायी रूप से छाया रहता है। सुख-दुख, हानि-लाभ, किसी भी दशशा मेें उसे बदलते नहीं देखा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('61257d69-a415-46e1-9c6e-78aa3d35c295', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन गधे का एक छोटटा भाई और भी है, जो उससे कम ही गधा है, और वह है ‘बैल’। जिस अर््थ मेें हम ‘गधा’ शशब्द का प्रयोग करते हैं, कुछ उसी से मिलते-जुलते अर््थ मेें ‘बछिया के ताऊ’ का भी प्रयोग करते हैं। कुछ लोग बैल को शशायद बेवकूफों मेें सर््वश्ेष्ठ कहेंगे; मगर हमारा विचार ऐसा नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cbcdf092-14c3-45ed-b1cc-11df8ece77ee', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बैल कभी-कभी मारता भी है, कभी-कभी अड़ियल बैल भी देखने में आता है। और भी कई रीतियों से अपना असंतोष प्रकट कर देता है; अतएव उसका स्थान गधे से नीचा है। झूरी के दोनों बैलों के नाम थे हीरा और मोती। दोनों पछाईं जाति के थे— देखने में सुंदर, काम में चौकस, डील में ऊँचे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6a969c1d-101a-422e-b68b-aaa45b1c1aa5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बहुत दिनों साथ रहते-रहते दोनों में भाईचारा हो गया था। दोनों आमने-सामने या आस-पास बैठे हुए एक-दूसरे से मूक-भाषा में विचार-विनिमय करते थे। एक, दूसरे के मन की बात कैसे समझ जाता था, हम नहीं कह सकते। अवश्य ही उनमें कोई ऐसी गुप्त शक्ति थी जिससे जीवों में श्रेष्ठता का दावा करने वाला मनुष्य वंचित है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0a39f2e0-f253-46fa-9da4-33cbe94902d4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों एक-दूसरे को चाटकर और सूँघकर अपना प्रेम प्रकट करते, कभी-कभी दोनों सींग भी मिला लिया करते थे— विग्रह के नाते से नहीं, केवल विनोद के भाव से, आत्मीयता के भाव से, जैसे दोस्तों में घनिष्ठता होते ही धौल-धप्पा होने लगता है। इसके बिना दोस्ती कुछ फुसफुसी, कुछ हल्की-सी रहती है, जिस पर ज्यादा विश्वास नहीं किया जा सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('193bac93-b325-4b86-bb21-52462bb04f52', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जिस वक्त ये दोनों बैल हल या गाड़ी में जोत दिए जाते और गरदन हिला-हिलाकर चलते, उस वक्त हरएक की यही चेष्टा होती थी कि ज्यादा-से-ज्यादा बोझ मेरी ही गरदन पर रहे। दिन-भर के बाद दोपहर या संध्या को दोनों खुलते, तो एक-दूसरे को चाट-चूटकर अपनी थकान मिटा लिया करते। नाँद में खली-भूसा पड़ जाने के बाद दोनों साथ उठते, साथ नाँद में मुँह डालते और साथ ही बैठते थे। एक मुँह हटा लेता, तो दूसरा भी हटा लेता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('43bfea3e-b63a-47e4-88fa-65c3e1f13552', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संयोग की बात, झूरी ने एक बार गोई को ससुराल भेज दिया। बैलों को क्या मालूम, वे क्यों भेजे जा रहे हैं। समझे, मालिक ने हमें बेच दिया। अपना यों बेचा जाना उन्हें अच्छा लगा या बुरा, कौन जाने, पर झूरी के साले गया को घर तक गोई ले जाने में दाँतों पसीना आ गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5becce27-820e-478c-ac4a-fb40a73fddb5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पीछे से हाँकता तो दोनों दाएँ-बाएँ भागते; पगहिया पकड़कर आगे से खींचता, तो दोनों पीछे को जोर लगाते। मारता तो दोनों सींग नीचे करके हुँकारते। अगर ईश्वर ने उन्हें वाणी दी होती, तो झूरी से पूछते− तुम हम गरीबों को क्यों निकाल रहे हो? हमने तो तुम्हारी सेवा करने में कोई कसर नहीं उठा रखी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('81d1fe65-d546-4052-91c1-b3ae2f25fc0b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर इतनी मेहनत से काम न चलता था तो और काम ले लेते। हमें तो तुम्हारी चाकरी में मर जाना कबूल था। हमने कभी दाने-चारे की शिकायत नहीं की। तुमने जो कुछ खिलाया, वह सिर झुकाकर खा लिया, फिर तुमने हमें इस जालिम के हाथ क्यों बेच दिया?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d80d438a-0cdb-4e6b-8b82-b564e77bc404', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संध्या समय दोनों बैल अपने नए स्थान पर पहुँचे। दिन-भर के भूखे थे, लेकिन जब नाँद में लगाए गए, तो एक ने भी उसमें मुँह न डाला। दिल भारी हो रहा था। जिसे उन्होंने अपना घर समझ रखा था, वह आज उनसे छूट गया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b59c5264-4de2-4f93-8994-6ed50ebf7147', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह नया घर, नया गाँव, नए आदमी, सब उन्हें बेगानों-से लगते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a1d457be-02be-451e-9b34-ca3e31ef6825', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनोों ने अपनी मूक-भाषा में सलाह की, एक-दूसरे को कनखियोों से देखा और लेट गए। जब गाँव में सोता पड़ गया, तो दोनोों ने जोर मारकर पगहे तुड़ा डाले और घर की तरफ चले। पगहे बहुत मजबूत थे। अनुमान न हो सकता था कि कोई बैल उन््हें तोड़ सकेगा; पर इन दोनोों में इस समय दूनी शक्‍तति आ गई थी। एक-एक झटके में रस्ससियाँ टूट गइ«।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('660e3060-8246-4b2f-98e4-aa4adf20d2f1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी प्ातःकाल सोकर उठा, तो देखा कि दोनोों बैल चरनी पर खड़े हैं। दोनोों की गरदनोों में आधा-आधा गराँव लटक रहा है। घुटने तक पाँव कीचड़ से भरे हैं और दोनोों की आँखों में विद्ोहमय स््ननेह झलक रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fb77d5ea-a70a-451c-8de2-f654d89cd2ab', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी बैलों को देखकर स््ननेह से गद्गद हो गया। दौड़कर उन््हें गले लगा लिया। प्ेमालिंगन और चुंबन का वह दृश््य बड़ा ही मनोहर था। घर और गाँव के लड़के जमा हो गए और तालियाँ बजा-बजाकर उनका स््ववावागत करने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f5f8e6c6-133b-4f9b-ab57-89ed51a36775', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव के इतिहास में यह घटना अभूतपूर्व न होने पर भी महत्वपूर््ण थी। बाल-सभा ने निश्‍चय किया, दोनोों पशु-वीरों को अभिनंदन-पत्र देना चाहिए। कोई अपने घर से रोटियाँ लाया, कोई गुड़, कोई चोकर, कोई भूसी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('276f1db0-0239-4e36-bd8e-df0fd277d987', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बालक ने कहा− “ऐसे बैल किसी के पास न होंगे।” दूसरे ने समर््थन किया− “इतनी दूर से दोनोों अकेले चले आए।” तीसरा बोला− “बैल नहीीं हैं वे, उस जनम के आदमी हैं।” इसका प्रतिवाद करने का किसी को साहस न हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('320e551e-dd1a-4402-8b64-f5249b8ed962', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनोों ने अपनी मूक-भाषा में सलाह की, एक-दूसरे को कनखियोों से देखा और लेट गए। जब गाँव में सोता पड़ गया, तो दोनोों ने जोर मारकर पगहे तुड़ा डाले और घर की तरफ चले। पगहे बहुत मजबूत थे। अनुमान न हो सकता था कि कोई बैल उन््हें तोड़ सकेगा; पर इन दोनोों में इस समय दूनी शक्‍तति आ गई थी। एक-एक झटके में रस्ससियाँ टूट गइ«। झूरी प्ातःकाल सोकर उठा, तो देखा कि दोनोों बैल चरनी पर खड़े हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('94adf232-e45d-4802-a6d3-c2d878786a86', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनोों की गरदनोों में आधा-आधा गराँव लटक रहा है। घुटने तक पाँव कीचड़ से भरे हैं और दोनोों की आँखों में विद्ोहमय स््ननेह झलक रहा है। झूरी बैलों को देखकर स््ननेह से गद्गद हो गया। दौड़कर उन््हें गले लगा लिया। प्ेमालिंगन और चुंबन का वह दृश््य बड़ा ही मनोहर था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('731e9a8e-93ea-4c63-9401-a45212e1a046', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर और गाँव के लड़के जमा हो गए और तालियाँ बजा-बजाकर उनका स््ववावागत करने लगे। गाँव के इतिहास में यह घटना अभूतपूर्व न होने पर भी महत्वपूर््ण थी। बाल-सभा ने निश्‍चय किया, दोनोों पशु-वीरों को अभिनंदन-पत्र देना चाहिए। कोई अपने घर से रोटियाँ लाया, कोई गुड़, कोई चोकर, कोई भूसी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d036df00-e24b-41d1-9a9a-e0dd357aa73c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बालक ने कहा− “ऐसे बैल किसी के पास न होंगे।” दूसरे ने समर््थन किया− “इतनी दूर से दोनोों अकेले चले आए।” तीसरा बोला− “बैल नहीीं हैं वे, उस जनम के आदमी हैं।” इसका प्रतिवाद करने का किसी को साहस न हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('74866a05-64a5-4fdf-a2ca-1fa197bde158', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी की स्‍‍त््री्री ने बैलों को द्ार पर देखा, तो जल उठी। बोली− “कैसे नमक-हराम बैल हैं कि एक दिन वहाँ काम न किया; भाग खड़े हुए।”
झूरी अपने बैलों पर यह आक्ेप न सुन सका− “नमकहराम क््यों हैं? चारा-दाना कुछ न दिया होगा, तो क््ययाया करते?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f4db818b-6ab2-43bf-95c6-e4c4d239196d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स्‍‍त््री्री ने रोब के साथ कहा− “बस, तुम््हीं तो बैलों को खिलाना जानते हो और तो सभी पानी पिला-पिलाकर रखते हैं।”
झूरी ने चिढ़ाया− “चारा मिलता तो क््यों भागते?”
स्‍‍त््री्री चिढ़ी− “भागे इसलिए कि वे लोग तुम-जैसे बुद्धुुओं की तरह बैलों को सहलाते नहीं। खिलाते हैं, तो रगड़कर जोतते भी हैं। ये दोनों ठहरे कामचोर, भाग निकले।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('94a47065-1d0c-4d20-86fd-46ff4f1b3ae9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अब देखूँ, कहाँ से खली और चोकर मिलता है! सूखे भूसे के सिवा कुछ न दूँगी, खाएँ चाहें मरेें।”
वही हुआ। मजूर को बड़ी ताकीद कर दी गई कि बैलों को खाली सूखा भूसा दिया जाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f7c58735-75e0-46e1-96b0-c19da68be230', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बैलों ने नाँद मेें मुँह डाला, तो फीका-फीका। न कोई चिकनाहटट, न कोई रस। क््ययाया खाएँ? आशशा-भरी आँखों से द्ार की ओर ताकने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('853066cf-21eb-4664-af77-eaac3f446252', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झूरी ने मजूर से कहा− “थोड़ी-सी खली क््यों नहीं डाल देता?”
“मालकिन मुझे मार ही डालेंगी।”
“चुराकर डाल आ।”
“ना दादा, पीछे से तुम भी उन््हीं की-सी कहोगे।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d1f26271-8bd7-45dc-bf8e-ac4cd29a351c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे दिन झूरी का साला फिर आया और बैलों को ले चला। अबकी उसने दोनों को गाड़ी मेें जोता।
दो-चार बार मोती ने गाड़ी को सड़क की खाई मेें गिराना चाहा; पर हीरा ने संभाल लिया। वह ज्यादा सहनशशील था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('04c9d626-2bf5-46bf-b343-fcfd1b8f77a9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संध्या-समय घर पहुँचकर उसने दोनों को मोटटी रस््ससियों से बाँधा और कल की शशरारत का मजा चखाया। फिर वही सूखा भूसा डाल दिया। अपने दोनों बैलों को खली, चूनी सब कुछ दी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2eaf3f0f-aff6-4373-a38d-74880f584e2c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों बैलों का ऐसा अपमान कभी न हुआ था। झूरी इन््हें फूल की छड़ी से भी न छूता था। उसकी टिटटकार पर दोनों उड़ने लगते थे। यहाँ मार पड़ी। आहत सम््ममान की व्यथा तो थी ही, उस पर मिला सूखा भूसा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fc41a1cc-2242-4326-9311-c1fcff5389e3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नाँद की तरफ आँखें तक न उठाइ«।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6e05d74-fe8a-4148-9c7b-16bd88963c44', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे दिन गया ने बैलों को हल मेें जोता, पर इन दोनों ने जैसे पाँव न उठाने की कसम खा ली थी। वह मारते-मारते थक गया; पर दोनों ने पाँव न उठाया। एक बार जब उस निर््दयी ने हीरा की नाक पर खूब डंडे जमाए, तो मोती का गुस््ससासा काबू के बाहर हो गया। हल लेकर भागा। हल, रस््ससीसी, जुआ, जोत, सब टटूटट-टटाटट कर बराबर हो गया। गले मेें बड़ी-बड़ी रस््ससियाँ न होतीं, तो दोनों पकड़ाई मेें न आते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('67b179d2-3f35-468e-803c-6b247bbfac07', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने मूक-भाषा मेें कहा− “भागना व््यर््थ है।” मोती ने उत्तर दिया− “तुम्हारी तो इसने जान ही ले ली थी।” “अबकी बड़ी मार पड़ेगी।” “पड़ने दो, बैल का जन््म लिया है, तो मार से कहाँ तक बचेंगे?” गया दो आदमियोों के साथ दौड़ा आ रहा है। दोनों के हाथों मेें लाठियाँ हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('428f014c-f013-44a1-8808-b25afb67b265', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती बोला− “कहो तो दिखा दूँ कुछ मजा मैं भी। लाठी लेकर आ रहा है।” हीरा ने समझाया– “नहीं भाई! खड़े हो जाओ।” “मुझे मारेगा, तो मैं भी एक-दो को गिरा दूँगा!” “नहीं। हमारी जाति का यह धर््म नहीं है।” मोती दिल मेें ऐंठकर रह गया। गया आ पहुँचा और दोनों को पकड़ कर ले चला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8f70c56c-3bff-4569-a105-dcf3c6e1f287', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुशशल हुई कि उसने इस वक्‍त मारपीटट न की, नहीं तो मोती भी पलटट पड़ता। उसके तेवर देखकर गया और उसके सहायक समझ गए कि इस वक्‍त टटाल जाना ही मसलहत है। आज दोनों के सामने फिर वही सूखा भूसा लाया गया। दोनों चुपचाप खड़े रहे। घर के लोग भोजन करने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4288bb36-120d-4124-ae6f-d4516f0c5e9d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस वक्‍त एक छोटटी-सी लड़की दो रोटियाँ लिए निकली और दोनों के मुँह मेें देकर चली गई। उस एक रोटटी से इनकी भूख तो क््ययाया शशांत होती; पर दोनों के हृदय को मानो भोजन मिल गया। यहाँ भी किसी सज््जन का वास है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a9437404-d569-4062-ae46-e431a9728b68', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लड़की भैरो की थी। उसकी माँ मर चुकी थी। सौतेली माँ उसे मारती रहती थी, इसलिए इन बैलों से उसे एक प्रकार की आत््ममीयता हो गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ccc5ff92-6339-4121-a289-c3fd6e0b76d7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे दिन गया ने बैलों को हल मेें जोता, पर इन दोनों ने जैसे पाँव न उठाने की कसम खा ली थी। वह मारते-मारते थक गया; पर दोनों ने पाँव न उठाया। एक बार जब उस निर््दयी ने हीरा की नाक पर खूब डंडे जमाए, तो मोती का गुस््ससासा काबू के बाहर हो गया। हल लेकर भागा। हल, रस््ससीसी, जुआ, जोत, सब टटूटट-टटाटट कर बराबर हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('26220a96-07f9-44f2-a973-a07543d8a368', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती बोला− “कहो तो दिखा दूँ कुछ मजा मैं भी। लाठी लेकर आ रहा है।” हीरा ने समझाया– “नहीं भाई! खड़े हो जाओ।” “मुझे मारेगा, तो मैं भी एक-दो को गिरा दूँगा!” “नहीं। हमारी जाति का यह धर््म नहीं है।” मोती दिल मेें ऐंठकर रह गया। गया आ पहुँचा और दोनों को पकड़ कर ले चला। कुशशल हुई कि उसने इस वक्‍त मारपीटट न की, नहीं तो मोती भी पलटट पड़ता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2beb23d2-efc0-4ee9-9188-2f24f50221c8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज दोनों के सामने फिर वही सूखा भूसा लाया गया। दोनों चुपचाप खड़े रहे। घर के लोग भोजन करने लगे। उस वक्‍त एक छोटटी-सी लड़की दो रोटियाँ लिए निकली और दोनों के मुँह मेें देकर चली गई। उस एक रोटटी से इनकी भूख तो क््ययाया शशांत होती; पर दोनों के हृदय को मानो भोजन मिल गया। यहाँ भी किसी सज््जन का वास है। लड़की भैरो की थी। उसकी माँ मर चुकी थी। सौतेली माँ उसे मारती रहती थी, इसलिए इन बैलों से उसे एक प्रकार की आत््ममीयता हो गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1800100f-0b42-4642-b151-20fd7abe0a95', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खिला जाती। प्रेम के इस प्रसाद की यह बरकत थी कि दो-दो गाल सूखा भूसा खाकर भी दोनों दुर््बल न होते थे, मगर दोनों की आँखों मेें, रोम-रोम मेें विद्ोह भरा हुआ था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('395df38d-4af7-40b9-aa1b-65e259a8fa41', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन मोती ने मूक-भाषा मेें कहा− “अब तो नहीं सहा जाता, हीरा!” “क््ययाया करना चाहते हो?” “एकाध को सींगों पर उठाकर फेेंक दूँगा।” “लेकिन जानते हो, वह प्यारी लड़की, जो हमेें रोटियाँ खिलाती है, उसी की लड़की है, जो इस घर का मालिक है। यह बेचारी अनाथ न हो जाएगी?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('89c8c65f-a19a-450e-9fce-ff00b93a5bb4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तो मालकिन को न फेेंक दूँ। वही तो उस लड़की को मारती है।” “लेकिन औरत जात पर सींग चलाना मना है, यह भूले जाते हो।” “तुम तो किसी तरह से निकलने ही नहीं देते। बताओ, तुड़ाकर भाग चलें।” “हाँ, यह मैं स््ववीवीकार करता, लेकिन इतनी मोटटी रस््ससीसी टटूटटेगी कैसे?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('081693ca-c299-4213-b3e3-3c0589a588d9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसका एक उपाय है। पहले रस्্সसीसी को थोड़ा-सा चबा लो। फिर एक झटटके मेें टटूटट जाती है।” रात को जब बालिका रोटियाँ खिलाकर चली गई, तो दोनों रस्্সसियाँ चबाने लगे, पर मोटटी रस्্সसीसी मुँह मेें न आती थी। बेचारे बार-बार जोर लगाकर रह जाते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c48f1055-608c-440f-85b2-c61652ab4848', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा घर का द्ार खुला और वही लड़की निकली। दोनों सिर झुकाकर उसका हाथ चाटटने लगे। दोनों की पूँछें खड़ी हो गइ«। उसने उनके माथे सहलाए और बोली– “खोले देती हूँ। चुपके से भाग जाओ, नहीं तो यहाँ लोग तुम््हें मार डालेंगे। आज घर मेें सलाह हो रही है कि इनकी नाकों मेें नाथ डाल दी जाएँ।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b43717d5-5602-4c43-8f68-70fdf780e153', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसने गराँव खोल दिया, पर दोनों चुपचाप खड़े रहे। मोती ने अपनी भाषा मेें पूछा− “अब चलते क््यों नहीं?” हीरा ने कहा− “चलें तो, लेकिन कल इस अनाथ पर आफत आएगी। सब इसी पर संदेह करेंगे।” सहसा बालिका चिल्लाई− “दोनों फूफावाले बैल भागे जा रहे हैं। ओ दादा! दादा! दोनों बैल भागे जा रहे हैं, जल्दी दौड़ो।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('08bea358-203c-47aa-8e42-6dcb19b77a0d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गया हड़बड़ाकर भीतर से निकला और बैलों को पकड़ने चला। वे दोनों भागे। गया ने पीछा किया। वह और भी तेज हुए। गया ने शशोर मचाया। फिर गाँव के कुछ आदमियोों को भी साथ लेने के लिए लौटटा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('41b57d7b-8a48-4c78-8d52-e1bb6155398b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों मित्रों को भागने का मौका मिल गया। सीधे दौड़ते चले गए। यहाँ तक कि मार््ग का ज्ान न रहा। जिस परिचित मार््ग से आए थे, उसका यहाँ पता न था। नए-नए गाँव मिलने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c2b954bc-b2fd-46bc-8f67-87512e78a837', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब दोनों एक खेत के किनारे खड़े होकर सोचने लगे, अब क््ययाया करना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e2d4298d-eb33-402d-86c6-10beaef6aac9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने कहा− “मालूम होता है, राह भूल गए।” “तुम भी बेतहाशा भागे। वहीं उसे मार गिराना था।” “उसे मार गिराते, तो दुनिया क्या कहती? वह अपना धर्म छोड़ दे, लेकिन हम अपना धर्म क्यों छोड़ें?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a21b7d8d-1f0b-48b7-9995-cca62ca7db1f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों भूख से व्याकुल हो रहे थे। खेत में मटर खड़ी थी। चरने लगे। रह-रहकर आहट ले लेते थे, कोई आता तो नहीं है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2b9239ee-8897-4e9b-bf1a-ad8ba160fff2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब पेट भर गया और दोनों ने आजादी का अनुभव किया तो मस्त होकर उछलने-कूदने लगे। पहले दोनों ने डकार ली। फिर सींग मिलाए और एक-दूसरे को ठेलने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6d263ebc-61e4-410d-9f51-1bc65666089e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने देखा− खेल में झगड़ा हुआ चाहता है तो किनारे हट गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c4a8dbb4-21dd-458a-bd5b-87dddfc680f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अरे! यह क्या? कोई साँड़ डौंकता चला आ रहा है। हाँ, साँड़ ही है। वह सामने आ पहुँचा। दोनों मित्र बगलें झाँक रहे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4e3f348e-646d-434e-bed3-d135b1de9564', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साँड़ पूरा हाथी है। उससे भिड़ना जान से हाथ धोना है; लेकिन न भिड़ने पर भी तो जान बचती नहीं नजर आती। इन्हीं की तरफ आ भी रहा है। कितनी भयंकर सूरत है!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ff4dcc9f-65f3-4c28-a711-f95fb1ce2eef', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने मूक-भाषा में कहा− “बुरे फँसे। जान बचेगी? कोई उपाय सोचो।” हीरा ने चिंतित स्वर में कहा− “अपने घमंड में भूला हुआ है। आरजू-विनती न सुनेगा।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f8f8b3f8-1e92-4fda-a74d-a46d587724bc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“भाग क्यों न चलें?” “भागना कायरता है।” “तो फिर यहीं मरो। बंदा तो नौ-दो-ग्यारह होता है।” “और जो दौड़ाए?” “तो फिर कोई उपाय सोचो जल्द!”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5071c36e-9e38-4cb0-9b3a-2d4f9175980b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साँड़ चाहता था कि एक-एक करके... (अधूरा वाक्य)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('573a3d6c-145e-494c-ab1e-ed35bfee90eb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने सिर लटटकाए हुए जवाब दिया− “मुझे तो मालूम होता है, प्राणण निकल रहे हैं।” “इतनी जल्द हिम््मत न हारो भाई! यहाँ से भागने का कोई उपाय निकालना चाहिए।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2949f913-66aa-4e2c-8b01-1b95e4ece4a4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाड़े की दीवार कच्ची थी। हीरा मजबूत तो था ही, अपने नुकीले सींग दीवार मेें गड़ा दिए और जोर मारा, तो मिटट्टटी का एक चिप्पड़ निकल आया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1713487c-80d4-41ba-bc19-9139588089fd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसी समय काँजीहौस का चौकीदार लालटटेन लेकर जानवरों की हाजिरी लेने आ निकला। हीरा का यह उजड्डपन देखकर उसने उसे कई डंडे रसीद किए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a1310e9f-3ab7-4291-a694-3c103214e4e0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने पड़े-पड़े कहा− “आखिर मार खाई, क््ययाया मिला?” “अपने बूते-भर जोर तो मार दिया।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0a71fa70-f3d1-41f3-aea2-867734db168a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“ऐसा जोर मारना किस काम का कि और बंधन मेें पड़ गए।” “जोर तो मारता ही जाऊँगा, चाहे कितने ही बंधन पड़ते जाएँ।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d8864e44-ce5f-47d1-8fcf-3a892057e0a6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“जान से हाथ धोना पड़ेगा।” “कुछ परवाह नहीं। यों भी तो मरना ही है। सोचो, दीवार खुद जाती तो कितनी जानें बच जातीं।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('00c8b21c-ea34-4b19-a914-c5ab4954fab3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“हाँ, यह बात तो है। अच्छा, तो ला, फिर मैं भी जोर लगाता हूँ।” मोती ने भी दीवार मेें उसी जगह सींग मारा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('097edcd9-550c-44b2-8ec4-382a5950056b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर तो वह दीवार मेें सींग लगाकर इस तरह जोर करने लगा, मानो किसी प्रतिद्ंद्ी से लड़ रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c7b382e3-52cb-4df3-9366-b0de660c32e5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आखिर कोई दो घंटटे की जोर-आजमाई के बाद दीवार ऊपर से लगभग एक हाथ गिर गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b70401a7-39bd-456e-a955-b6ac8ab9b0f4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दीवार का गिरना था कि अधमरे-से पड़े हुए सभी जानवर चेत उठे। तीनों घोड़़ियाँ सरपटट भाग निकलीं। फिर बकरियाँ निकलीं। इसके बाद भैंसें भी खिसक गइ; पर गधे अभी तक ज््यों-के-त््यों खड़े थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6e6bf948-5797-4d23-b50f-e507e310da9c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने पूछा− “तुम दोनों क््यों नहीं भाग जाते?” एक गधे ने कहा− “जो कहीं फिर पकड़ लिए जाएँ!” “तो क््ययाया हरज है। अभी तो भागने का अवसर है।” “हमेें तो डर लगता है, हम यहीं पड़े रहेंगे।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('245d94cf-d12c-479b-a491-9193b195f9dd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने आँखों मेें आँसू लाकर कहा− “तुम मुझे इतना स््ववार्थी समझते हो, हीरा? हम और तुम इतने दिनों एक साथ रहे हैं। आज तुम विपत्ति मेें पड़ गए, तो मैं तुम््हें छोड़कर अलग हो जाऊँ।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4110dbef-4905-4509-a2ec-97aa3b1cce8b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हीरा ने कहा− “बहुत मार पड़ेगी। लोग समझ जाएँगे यह तुम्हारी शशरारत है।” मोती गर््व से बोला− “जिस अपराध के लिए तुम्हारे गले मेें बंधन पड़ा, उसके लिए अगर मुझ पर मार पड़े, तो क््ययाया चिंता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6fd7e05-44e1-4f54-87c8-84b5d3e0c35a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह कहते हुए मोती ने दोनों गधों को सींगों से मार-मारकर बाड़े के बाहर निकाला और तब अपने बंधु के पास आकर सो रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('393298af-82d0-4dc8-a45d-67e34dc7ca03', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भोर होते ही मुंशशी और चौकीदार तथा अन्य कर््मचारियों मेें कैसी खलबली मची, इसके लिखने की जरूरत नहीं। बस, इतना ही काफी है कि मोती की खूब मरम््मत हुई और उसे भी मोटटी रस््ससीसी से बाँध दिया गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6392d97e-7f7f-4b1a-be98-076161ac359c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक सप्ताह तक दोनों मित्र वहाँ बँधे पड़े रहे। किसी ने चारे का एक तृणण भी न डाला। हाँ, एक बार पानी दिखा दिया जाता था। यही उनका आधार था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a858df53-d8f6-4087-b2f6-777ac769dce6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों इतने दुर््बल हो गए थे कि उठा तक न जाता था; ठठरियाँ निकल आई थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eb8d57ac-3a83-44d7-8f48-fe4651751eac', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन बाड़े के सामने डुग्गी बजने लगी और दोपहर होते-होते वहाँ पचास-साठ आदमी जमा हो गए। तब दोनों मित्र निकाले गए और उनकी देखभाल होने लगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a96d54f3-53c8-45b7-9bf7-ac3f8295e6c3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दढ़ियल आदमी की आँखें लाल थीं और मुद्रा अत्यंत कठोर थी। वह बैलों के कूल्हों में उँगली गोदकर मुंशी जी से बात कर रहा था। बैलों को यह समझने में देर न लगी कि वह कौन है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('7653808b-51c5-4790-af7f-1fbc5bc01fc3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मोती ने अश्रद्धा के भाव से कहा कि भगवान सबके ऊपर दया करते हैं, पर उन पर क्यों नहीं। हीरा ने उसे समझाया कि भगवान के लिए मरना-जीना बराबर है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('77f3e29a-143a-4787-91b0-2195de3cc824', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नीलाम होने के बाद दढ़ियल ने बैलों को डंडे के जोर पर चलाया। बैलों की बोटटी-बोटटी काँप रही थी, फिर भी वे भय के मारे भाग रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
