  ('a8507c1a-50b3-488e-a063-b3acd02fbd5e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a6c6489-858a-4ac6-b59a-826d72e7c9dc', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब दढ़ियल हारकर चला गया, तो मोती अकड़ता हुआ लौटा। हीरा ने कहा—'मैं डर रहा था कि कहीं तुम गुस्से में आकर मार न बैठो।' 'अगर वह मुझे पकड़ता, तो मैं बे-मारे न छोड़ता।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-131Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
